describe('Image Upload - Paste from Clipboard', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should successfully paste an image from clipboard into upload area', () => {
    // Setup: intercept the file upload API
    cy.intercept('POST', '/api/upload').as('uploadImage');

    // Get the upload area element
    cy.get('[data-testid="upload-area"]').should('be.visible');

    // Simulate clipboard content with an image file
    cy.window().then((win) => {
      const imageFile = new File([new Uint8Array(0), 'image/png'], 'clipboard-image.png', { type: 'image/png' });
      win.clipboardData = {
        files: [imageFile]
      };
    });

    // Trigger paste event in the upload area
    cy.get('[data-testid="upload-area"]').trigger('paste');

    // Verify the image preview appears
    cy.get('[data-testid="image-preview"]').should('be.visible');
    cy.get('[data-testid="image-preview img"]').should('have.attr', 'src');

    // Verify the upload button is enabled
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');

    // Verify the upload API was called
    cy.get('[data-testid="upload-button"]').click();
    cy.wait('@uploadImage');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Image uploaded successfully');
  });

  it('should handle pasting invalid or non-image data from clipboard', () => {
    // Setup: intercept the upload API
    cy.intercept('POST', '/api/upload').as('uploadImage');

    // Get the upload area element
    cy.get('[data-testid="upload-area"]').should('be.visible');

    // Simulate clipboard content with plain text
    cy.window().then((win) => {
      win.clipboardData = {
        files: [new File(['this is not an image'], 'text-file.txt', { type: 'text/plain' })]
      };
    });

    // Trigger paste event
    cy.get('[data-testid="upload-area"]').trigger('paste');

    // Verify no image preview appears
    cy.get('[data-testid="image-preview"]').should('not.exist');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid file type');

    // Verify upload button remains disabled
    cy.get('[data-testid="upload-button"]').should('be.disabled');

    // Verify upload API was not called
    cy.get('[data-testid="upload-button"]').click({ force: true });
    cy.get('@uploadImage').should('not.exist');
  });
});
